<template>\n  <div class="login-page">\n    <div class="login-container">\n      <h1>FocusFlow</h1>\n      <h2>Sign In</h2>\n      \n      <form @submit.prevent="handleLogin">\n        <div class="form-group">\n          <label for="email">Email</label>\n          <input v-model="email" type="email" id="email" required placeholder="your@email.com">\n        </div>\n        \n        <div class="form-group">\n          <label for="password">Password</label>\n          <input v-model="password" type="password" id="password" required placeholder="••••••••">\n        </div>\n        \n        <button type="submit" class="btn btn-submit" :disabled="loading">\n          {{ loading ? 'Signing in...' : 'Sign In' }}\n        </button>\n      </form>\n      \n      <p class="error" v-if="error">{{ error }}</p>\n      <p class="signup-link">Don't have an account? <router-link to="/register">Create one</router-link></p>\n    </div>\n  </div>\n</template>\n\n<script setup>\nimport { ref } from 'vue'\nimport { useAuthStore } from '../stores/auth.js'\nimport { useRouter } from 'vue-router'\n\nconst email = ref('')\nconst password = ref('')\nconst loading = ref(false)\nconst error = ref('')\nconst authStore = useAuthStore()\nconst router = useRouter()\n\nconst handleLogin = async () => {\n  loading.value = true\n  error.value = ''\n  \n  try {\n    await authStore.login(email.value, password.value)\n    router.push('/dashboard')\n  } catch (err) {\n    error.value = err.error || 'Login failed'\n  } finally {\n    loading.value = false\n  }\n}\n</script>\n\n<style scoped>\n.login-page {\n  min-height: 100vh;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n  padding: 20px;\n}\n\n.login-container {\n  background: white;\n  padding: 40px;\n  border-radius: 12px;\n  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);\n  width: 100%;\n  max-width: 400px;\n}\n\nh1 {\n  color: #667eea;\n  text-align: center;\n  margin-bottom: 10px;\n  font-size: 2rem;\n}\n\nh2 {\n  color: #333;\n  text-align: center;\n  margin-bottom: 30px;\n  font-weight: 600;\n}\n\nform {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n}\n\n.form-group {\n  display: flex;\n  flex-direction: column;\n}\n\nlabel {\n  color: #333;\n  font-weight: 600;\n  margin-bottom: 8px;\n}\n\ninput {\n  padding: 12px;\n  border: 2px solid #e0e0e0;\n  border-radius: 6px;\n  font-size: 1rem;\n  transition: border-color 0.3s;\n}\n\ninput:focus {\n  outline: none;\n  border-color: #667eea;\n}\n\n.btn-submit {\n  padding: 12px;\n  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n  color: white;\n  border: none;\n  border-radius: 6px;\n  font-size: 1rem;\n  font-weight: 600;\n  cursor: pointer;\n  transition: all 0.3s;\n}\n\n.btn-submit:hover:not(:disabled) {\n  transform: translateY(-2px);\n  box-shadow: 0 10px 20px rgba(102, 126, 234, 0.3);\n}\n\n.btn-submit:disabled {\n  opacity: 0.7;\n  cursor: not-allowed;\n}\n\n.error {\n  color: #e74c3c;\n  background: #fadbd8;\n  padding: 10px;\n  border-radius: 6px;\n  text-align: center;\n}\n\n.signup-link {\n  text-align: center;\n  color: #666;\n  margin-top: 20px;\n}\n\n.signup-link a {\n  color: #667eea;\n  text-decoration: none;\n  font-weight: 600;\n}\n\n.signup-link a:hover {\n  text-decoration: underline;\n}\n</style>\n